package com.example.hjp.v5

import com.example.hjp.deviceeval.V5ContactDependencyRule
import com.example.hjp.eval.v5.V5ContactDependencyContract
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * What the phone carries is what the document says.
 *
 * The contact-dependency contract lives in a JSON document, and the host evaluator parses it. A
 * device cannot do the same: the instrumentation APK's assets come from one digest-checked source
 * list generated by the build, and threading a second copy of the document through it — to be
 * re-parsed on the phone, against nothing — would put a second authority in the artefact.
 *
 * So [V5ContactDependencyRule.PRODUCTION_CONTRACT] restates it in Kotlin, and this asserts here, on
 * the host, before the APK is built and before the freeze pins either of them, that the restatement
 * and the document are the same contract. A drift is a failing test on this machine rather than a
 * phone scoring a 386-turn run by a rule nobody compared.
 */
class V5DeviceContractRestatementTest {

    private val document = V5ContactDependencyContract.load().rule()
    private val device = V5ContactDependencyRule.PRODUCTION_CONTRACT

    @Test
    fun `the device restatement and the document declare the same action tools`() {
        assertEquals(document.actionRules.keys.sorted(), device.actionRules.keys.sorted())
    }

    @Test
    fun `each action tool's contact targets are identical`() {
        document.actionRules.forEach { (tool, declared) ->
            assertEquals(
                "contact targets for $tool",
                declared.targets.sortedBy { it.path },
                device.actionRules.getValue(tool).targets.sortedBy { it.path },
            )
        }
    }

    @Test
    fun `each action tool's pure paths are identical`() {
        document.actionRules.forEach { (tool, declared) ->
            assertEquals(
                "pure paths for $tool",
                declared.pure.sorted(),
                device.actionRules.getValue(tool).pure.sorted(),
            )
        }
    }

    @Test
    fun `each action tool's stored-target requirement is identical`() {
        document.actionRules.forEach { (tool, declared) ->
            assertEquals(
                "requiresStoredCardTarget for $tool",
                declared.requiresStoredCardTarget,
                device.actionRules.getValue(tool).requiresStoredCardTarget,
            )
        }
    }

    @Test
    fun `the read tools, the verified path and the nested scan are identical`() {
        assertEquals(document.rankingTools, device.rankingTools)
        assertEquals(document.verificationTool, device.verificationTool)
        assertEquals(document.verifiedCardPath, device.verifiedCardPath)
        assertEquals(document.nestedScan, device.nestedScan)
    }

    @Test
    fun `the whole contract is equal`() {
        assertEquals(document, device)
    }
}
